// GENERATED by AppWand from the pages' import settings. Do not edit: it is rewritten whenever they change.

/// A heading the imported file can have.
class ImportColumn {
  const ImportColumn(this.label, {this.required = false});
  final String label;

  /// Whether a new row cannot go without it.
  final bool required;
}

/// What ImportButton needs to know of a list page's import.
class ImportConfig {
  const ImportConfig({
    required this.formats,
    this.columns = const [],
    this.mode = 'add',
    this.matchBy = '',
    this.allOrNothing = false,
    this.maxRows = 5000,
    this.roles = const [],
  });

  /// 'csv' and/or 'xlsx'.
  final List<String> formats;

  /// The headings read from the file; empty when every column of the table is.
  final List<ImportColumn> columns;

  /// 'add' (every row is new), 'update' or 'skip' (rows already in the list).
  final String mode;

  /// The heading that tells which rows are already in the list.
  final String matchBy;

  /// Whether one row with a problem holds back the whole file.
  final bool allOrNothing;
  final int maxRows;

  /// Roles that may import; empty for everyone who can open the page.
  final List<String> roles;
}

/// The import of each list page that has one, by page id.
const Map<String, ImportConfig> appImports = {
};
